// The bot path must not change behaviour (plan review item 8).
//
// tests/fixtures/bot-golden/contain-plans.json and egress-transcripts.json are
// snapshots of what scripts/pi-bots/pi_contain.mjs and pi_egress.mjs produce.
// They were RECORDED ONCE, at the base sha, and are never regenerated by a
// later PR: a green run here means a refactor changed nothing observable. Any
// diff to either golden file (or to this test's normalisation) must be
// rejected in review — a regenerated golden proves nothing.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { buildContainCases, buildEgressTranscripts } from "./fixtures/bot-golden/cases.mjs";

const GOLDEN_DIR = join(dirname(fileURLToPath(import.meta.url)), "fixtures", "bot-golden");
const MISSING = "golden not recorded: run node tests/fixtures/bot-golden/record.mjs";

function readGolden(name) {
  try {
    return JSON.parse(readFileSync(join(GOLDEN_DIR, name), "utf8"));
  } catch (e) {
    if (e && e.code === "ENOENT") assert.fail(MISSING);
    throw e;
  }
}

test("the bot contain plan is byte-identical to the recorded golden", () => {
  const golden = readGolden("contain-plans.json");
  assert.deepEqual(buildContainCases(), golden);
});

test("the bot egress relay's transcripts are byte-identical to the recorded golden", async () => {
  const golden = readGolden("egress-transcripts.json");
  assert.deepEqual(await buildEgressTranscripts(), golden);
});